#!/usr/bin/env python3
from pathlib import Path
import json,hashlib,base64,zlib,subprocess,sys,datetime
ROOT=Path('/Users/murphyhoops/Documents/ueotlean-worktrees/core-books-handoff-20261020')
REPO=ROOT/'path-realization-20261022'; EVIDENCE=ROOT/'path-realization-evidence-20261022'
OUT=EVIDENCE/'final-source-sync-01'; OUT.mkdir(exist_ok=False)
BASE='d503586107974c56e0773b4ea106b41a7d144b43'
payload=json.loads(zlib.decompress(base64.b64decode('')))
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=REPO,text=True).strip()==BASE
records=[]
for row in payload['files']:
 path=REPO/row['path']; data=base64.b64decode(row['content_b64']); assert hashlib.sha256(data).hexdigest()==row['sha256']
 old=path.read_bytes() if path.exists() else None
 path.parent.mkdir(parents=True,exist_ok=True); path.write_bytes(data); assert path.read_bytes()==data
 records.append({'path':row['path'],'sha256':row['sha256'],'prior_sha256':hashlib.sha256(old).hexdigest() if old is not None else None})
protocol=REPO/'formalization/ueot-core/docs/compression/theory_completion/unified_closure/path_realization_v1/native_protocol'
sys.path.insert(0,str(protocol)); import protocol_adapter
_,actual=protocol_adapter.source_corpus(REPO);assert actual==payload['source_tree_sha256']
manifest=EVIDENCE/'FROZEN_INPUTS_FINAL_01.json'; assert not manifest.exists()
command=['python3','-B',str(protocol/'freeze_inputs.py'),'--repo',str(REPO),'--base-ref',BASE,'--output',str(manifest)]
p=subprocess.run(command,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
(OUT/'freeze.log').write_bytes(p.stdout); assert p.returncode==0,p.stdout.decode(errors='replace')
assert hashlib.sha256(manifest.read_bytes()).hexdigest()==payload['frozen_manifest_sha256']
receipt={'schema':'PATH_REALIZATION_FINAL_SOURCE_SYNC_V1','state':'PASS_CLOUD_MAC_SOURCE_AND_FROZEN_INPUTS_IDENTICAL','base':BASE,'source_tree_sha256':actual,'module_count':691,'synced':records,'frozen_inputs_sha256':payload['frozen_manifest_sha256'],'freeze_command':command,'freeze_exit':p.returncode,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
(OUT/'RECEIPT.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({'state':receipt['state'],'source_tree_sha256':actual,'module_count':691,'files':len(records),'manifest_sha256':receipt['frozen_inputs_sha256']}))
